message.content:
{
  "description": "The creature is shown in left-facing profile standing on sandy ground against a plain light background. It is a quadrupedal chimera with the head, legs, and long bushy tail of a reddish fox and the neck, chest, back, and folded wings of a barn owl. The front of the animal from the nose to the upper neck and the four legs and tail are covered in dense fox-like fur in reddish-orange and brown with white on the muzzle and chest, while the lower neck, chest, belly, back and sides are covered in pale owl-like feathers in white, buff, and mottled gray-brown with dark spotting and barring. Two folded feathered wings lie flat along the sides of the mid-body, and the overall posture and proportions are those of a standing fox.",
  "parts": [
    {
      "part": "head",
      "looks_like": "a fox head in profile facing left, with a pointed muzzle, black nose, white fur around the mouth and lower cheek, reddish-orange fur on the bridge of the nose and around the amber eye, fine whiskers on the muzzle, and a slightly open mouth",
      "where": "at the front and top of the body, atop the neck"
    },
    {
      "part": "ears",
      "looks_like": "two large upright triangular pointed ears with reddish-brown outer fur, black edging along the back, and pale cream and dark brown interior fur with visible inner detail",
      "where": "on top of the head, one slightly behind the other in profile view"
    },
    {
      "part": "legs",
      "looks_like": "four sturdy mammalian legs covered in reddish-brown fur that darkens to dark brown to black on the lower shanks, front legs straight and vertical, hind legs bent at the hock joint",
      "where": "under the body, two front legs under the chest and two hind legs under the rear torso, supporting the body on the ground"
    },
    {
      "part": "feet",
      "looks_like": "four fur-covered paws with visible dark claws and toe pads, rounded at the toes, with darker fur blending into the lower leg",
      "where": "at the bottom ends of the four legs, in contact with the sandy ground"
    },
    {
      "part": "tail",
      "looks_like": "one long, thick, very bushy tail covered in long reddish-brown fur with lighter tan and cream on the underside and tip, tapering slightly toward the end",
      "where": "extending from the rear of the body to the right and downward, nearly touching the ground behind the hind legs"
    },
    {
      "part": "wings",
      "looks_like": "two folded wings with layered flight feathers in barn-owl patterning of buff, cream, white, and gray with black spots and dark barring, the primaries overlapping toward the rear",
      "where": "along the left and right sides of the mid-back and torso, overlying the fur of the sides"
    },
    {
      "part": "feathers",
      "looks_like": "dense soft plumage covering the lower neck, chest, belly, back and wings, white and pale buff on the chest and underside, mottled gray-brown on the back and wing coverts, with layered overlapping vanes",
      "where": "on the neck below the fox fur, across the chest and belly, over the back, and forming the wings"
    },
    {
      "part": "markings",
      "looks_like": "small scattered black and dark brown spots on the white and buff chest and neck, larger mottled gray patches with white-centered black spots on the back and wing coverts, and dark brown to black bars and spots on the flight feathers",
      "where": "scattered across the feathered chest, neck, back, and wings"
    }
  ],
  "attached_objects": [],
  "animals": ["fox", "barn owl"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 2,
  "extra_limb_pieces": 0,
  "tails": 1
}
